 catching up fast\" },\n  { stat: \"Regional\", label: \"disparities persist\", detail: \"Scandinavia leads; MENA & Africa lag\" }\n];\n\ntakeaways.forEach((item, i) => {\n  const x = 0.5 + i * 3.1;\n\n  slide9.addShape(pres.shapes.RECTANGLE, {\n    x: x, y: 1.2, w: 2.9, h: 2.4,\n    fill: { color: \"2A3F54\" }\n  });\n\n  slide9.addText(item.stat, {\n    x: x, y: 1.35, w: 2.9, h: 0.7,\n    fontSize: 32, fontFace: \"Arial\", bold: true,\n    color: COLORS.accent, align: \"center\", margin: 0\n  });\n\n  slide9.addText(item.label, {\n    x: x, y: 2.0, w: 2.9, h: 0.4,\n    fontSize: 13, fontFace: \"Arial\", bold: true,\n    color: COLORS.white, align: \"center\", margin: 0\n  });\n\n  slide9.addText(item.detail, {\n    x: x + 0.15, y: 2.4, w: 2.6, h: 0.9,\n    fontSize: 11, fontFace: \"Calibri\",\n    color: COLORS.muted, align: \"center\"\n  });\n});\n\n// Forward-looking statement\nslide9.addShape(pres.shapes.RECTANGLE, {\n  x: 0.5, y: 3.85, w: 9.0, h: 1.3,\n  fill: { color: COLORS.primary }\n});\n\nslide9.addText(\"The transition must accelerate. Transport and heating lag far behind electricity in the renewable transition, keeping the overall primary energy share much lower than the electricity share. To meet climate targets, wind and solar growth must continue to rapidly scale.\", {\n  x: 0.7, y: 4.0, w: 8.6, h: 1.0,\n  fontSize: 13, fontFace: \"Calibri\",\n  color: COLORS.white, align: \"left\", valign: \"middle\"\n});\n\n// Source\nslide9.addText(\"Source: Our World in Data  |  Data: Ember (2026); Energy Institute (2025)\", {\n  x: 0.5, y: 5.2, w: 8, h: 0.25,\n  fontSize: 10, fontFace: \"Calibri\",\n  color: COLORS.muted, align: \"left\"\n});\n\n// Save the presentation\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" })\n  .then(() => console.log(\"Presentation saved to /app/output/final_deck.pptx\"))\n  .catch(err => console.error(\"Error:\", err));", "numLines": 668, "startLine": 1, "totalLines": 668}}

