const pptxgen = require("pptxgenjs");
const path = require("path");

// Color palette - Clean Energy theme
const COLORS = {
  primary: "0D6E6E",      // Deep teal (renewable energy)
  secondary: "14A085",    // Seafoam green
  accent: "F4A261",       // Amber/orange (energy)
  dark: "1A2634",         // Dark navy for title slides
  light: "F8FAFB",        // Off-white for content
  text: "2D3748",         // Dark gray for body
  muted: "718096",        // Muted gray for secondary text
  white: "FFFFFF"
};

// Shadow factory to avoid mutation issues
const makeShadow = () => ({
  type: "outer",
  color: "000000",
  blur: 4,
  offset: 2,
  angle: 135,
  opacity: 0.12
});

const makeCardShadow = () => ({
  type: "outer",
  color: "000000",
  blur: 6,
  offset: 2,
  angle: 135,
  opacity: 0.10
});

// Create presentation
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Our World in Data";
pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.dark };

// Decorative accent shape top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("Global Renewable Energy in 2025:", {
  x: 0.6, y: 1.6, w: 8.8, h: 0.8,
  fontSize: 38, fontFace: "Arial", bold: true,
  color: COLORS.white, align: "left", margin: 0
});

slide1.addText("How Far Have We Come?", {
  x: 0.6, y: 2.3, w: 8.8, h: 0.7,
  fontSize: 38, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", margin: 0
});

// Subtitle
slide1.addText("A data-driven overview of renewable energy's growing share in the global energy and electricity mix, spanning hydropower, wind, and solar technologies.", {
  x: 0.6, y: 3.3, w: 7.5, h: 0.9,
  fontSize: 15, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Source attribution
slide1.addText("Source: Our World in Data  |  Data: Ember (2026); Energy Institute (2025)", {
  x: 0.6, y: 5.0, w: 8, h: 0.3,
  fontSize: 11, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// ============================================================
// SLIDE 2: Fossil Fuel Dominance Context
// ============================================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.light };

// Title
slide2.addText("75% of Global GHG Emissions Still Come from Fossil Fuels", {
  x: 0.5, y: 0.4, w: 9, h: 0.7,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.dark, align: "left", margin: 0
});

// Large stat callout - left side
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.3, w: 4.3, h: 3.8,
  fill: { color: COLORS.white },
  shadow: makeCardShadow()
});

slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.3, w: 0.08, h: 3.8,
  fill: { color: COLORS.accent }
});

slide2.addText("5M+", {
  x: 0.7, y: 1.5, w: 3.9, h: 1.0,
  fontSize: 56, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", margin: 0
});

slide2.addText("premature deaths per year", {
  x: 0.7, y: 2.4, w: 3.9, h: 0.4,
  fontSize: 14, fontFace: "Calibri",
  color: COLORS.text, align: "left", margin: 0
});

slide2.addText("from air pollution caused by fossil fuel combustion", {
  x: 0.7, y: 2.75, w: 3.9, h: 0.5,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.muted, align: "left", margin: 0
});

slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 3.4, w: 3.8, h: 0.02,
  fill: { color: "E2E8F0" }
});

slide2.addText("Since the Industrial Revolution, fossil fuels have dominated global energy systems, driving both climate change and severe local air pollution.", {
  x: 0.7, y: 3.6, w: 3.8, h: 1.2,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.text, align: "left"
});

// Right side - key points
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 5.1, y: 1.3, w: 4.4, h: 3.8,
  fill: { color: COLORS.white },
  shadow: makeCardShadow()
});

slide2.addText("The Energy Transition Imperative", {
  x: 5.3, y: 1.5, w: 4, h: 0.4,
  fontSize: 16, fontFace: "Arial", bold: true,
  color: COLORS.dark, align: "left", margin: 0
});

slide2.addText([
  { text: "Three-quarters of global greenhouse gas emissions come from burning fossil fuels for energy", options: { bullet: true, breakLine: true } },
  { text: "To reduce CO\u2082 emissions and air pollution, the world must rapidly shift toward low-carbon energy sources", options: { bullet: true, breakLine: true } },
  { text: "Renewable technologies include solar, wind, hydropower, geothermal, bioenergy, wave, and tidal sources", options: { bullet: true } }
], {
  x: 5.3, y: 2.0, w: 4.0, h: 2.8,
  fontSize: 13, fontFace: "Calibri",
  color: COLORS.text, align: "left",
  paraSpaceAfter: 10
});

// ============================================================
// SLIDE 3: Renewables ~14% of Primary Energy
// ============================================================
let slide3 = pres.addSlide();
slide3.background = { color: COLORS.light };

// Title
slide3.addText("Renewables Now Supply ~14% of Global Primary Energy", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 26, fontFace: "Arial", bold: true,
  color: COLORS.dark, align: "left", margin: 0
});

slide3.addText("Primary energy encompasses electricity, transport, and heating combined (2024 data, substitution method).", {
  x: 0.5, y: 0.95, w: 9, h: 0.35,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Figure image - world map
slide3.addImage({
  path: "/app/benchmark/assets/figure_2.jpg",
  x: 0.5, y: 1.4, w: 6.0, h: 3.5
});

// Right side - key insight card
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 6.8, y: 1.4, w: 2.7, h: 3.5,
  fill: { color: COLORS.primary },
  shadow: makeCardShadow()
});

slide3.addText("~1/7", {
  x: 6.8, y: 1.7, w: 2.7, h: 0.9,
  fontSize: 44, fontFace: "Arial", bold: true,
  color: COLORS.white, align: "center", margin: 0
});

slide3.addText("of primary energy\nis renewable", {
  x: 6.8, y: 2.6, w: 2.7, h: 0.7,
  fontSize: 14, fontFace: "Calibri",
  color: COLORS.white, align: "center"
});

slide3.addShape(pres.shapes.RECTANGLE, {
  x: 7.2, y: 3.4, w: 1.9, h: 0.02,
  fill: { color: COLORS.white, transparency: 40 }
});

slide3.addText("Transport and heating remain heavily reliant on oil and gas, keeping the renewable share lower than in electricity.", {
  x: 7.0, y: 3.6, w: 2.5, h: 1.1,
  fontSize: 11, fontFace: "Calibri",
  color: COLORS.white, align: "center"
});

// ============================================================
// SLIDE 4: Renewable Electricity Generation Growth
// ============================================================
let slide4 = pres.addSlide();
slide4.background = { color: COLORS.light };

// Title
slide4.addText("Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 24, fontFace: "Arial", bold: true,
  color: COLORS.dark, align: "left", margin: 0
});

slide4.addText("Global renewable electricity generation by technology (2024 data)", {
  x: 0.5, y: 0.95, w: 9, h: 0.3,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Chart - Bar chart for generation data
const chartData = [{
  name: "Generation (TWh)",
  labels: ["Hydropower", "Wind", "Solar", "Other"],
  values: [4500, 2400, 2000, 700]
}];

slide4.addChart(pres.charts.BAR, chartData, {
  x: 0.5, y: 1.35, w: 5.5, h: 3.6,
  barDir: "col",
  chartColors: [COLORS.primary],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: false },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.dark,
  dataLabelFontSize: 11,
  showLegend: false,
  valAxisMaxVal: 5000
});

// Right side - data table
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.35, w: 3.2, h: 3.6,
  fill: { color: COLORS.white },
  shadow: makeCardShadow()
});

slide4.addText("Technology Breakdown", {
  x: 6.5, y: 1.5, w: 2.8, h: 0.4,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.dark, align: "left", margin: 0
});

// Table data
let tableData = [
  [
    { text: "Technology", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.white } },
    { text: "TWh", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.white } },
    { text: "Share", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.white } }
  ],
  ["Hydropower", "~4,500", "~47%"],
  ["Wind", "~2,400", "~25%"],
  ["Solar", "~2,000", "~21%"],
  ["Other", "~700", "~7%"]
];

slide4.addTable(tableData, {
  x: 6.5, y: 2.0, w: 2.8,
  colW: [1.1, 0.8, 0.9],
  fontSize: 11,
  fontFace: "Calibri",
  color: COLORS.text,
  border: { pt: 0.5, color: "E2E8F0" },
  align: "center",
  valign: "middle"
});

// Key insight
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.5, y: 4.0, w: 2.8, h: 0.75,
  fill: { color: COLORS.secondary, transparency: 15 }
});

slide4.addText("Wind + Solar combined now nearly match hydropower's output", {
  x: 6.6, y: 4.1, w: 2.6, h: 0.55,
  fontSize: 10, fontFace: "Calibri", bold: true,
  color: COLORS.primary, align: "center", valign: "middle"
});

// ============================================================
// SLIDE 5: Electricity Mix - One Third Renewable
// ============================================================
let slide5 = pres.addSlide();
slide5.background = { color: COLORS.light };

// Title
